//#region mcp/icons.ts
var nodes = Object.values([icon_nodes_default])[0];
var tags = Object.values([tags_default])[0];
var ICON_COUNT = Object.keys(nodes).length;
var escapeAttr = (value) => String(value).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
function iconSvg(name, options = {}) {
	const node = nodes[name];
	if (!node) return null;
	const size = options.size ?? 24;
	const children = node.map(([tag, attrs]) => `<${tag} ${Object.entries(attrs).map(([k, v]) => `${k}="${escapeAttr(v)}"`).join(" ")}/>`).join("");
	return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${options.strokeWidth ?? 2}" stroke-linecap="round" stroke-linejoin="round" class="icon icon-${name}">${children}</svg>`;
}
/** Icons whose name or tags match the query words, best matches first. */
function findIcons(query, limit = 40) {
	const words = query.toLowerCase().split(/[\s,]+/).filter(Boolean);
	if (!words.length) return [];
	const scored = [];
	for (const name of Object.keys(nodes)) {
		const parts = name.split("-");
		const tagList = tags[name] ?? [];
		let score = 0;
		for (const word of words) {
			if (name === word) score += 12;
			else if (parts.includes(word)) score += 8;
			else if (name.includes(word)) score += 4;
			if (tagList.some((tag) => tag === word)) score += 5;
			else if (tagList.some((tag) => tag.split(/\s+/).some((t) => t.startsWith(word)))) score += 2;
		}
		if (score > 0) scored.push([name, score - parts.length * .1]);
	}
	return scored.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, limit).map(([name]) => name);
}
